@namespace ghidra.features.@base.memsearch;

using static org.junit.Assert;



using org.junit;

using docking.action;
using ghidra.app.plugin.core.codebrowser;
using ghidra.app.plugin.core.marker;
using ghidra.app.plugin.core.programtree;
using ghidra.features.@base.memsearch.gui;
using ghidra.features.@base.memsearch.gui;
using ghidra.features.@base.memsearch.mnemonic;
using ghidra.framework.plugintool;
using ghidra.program.database;
using ghidra.program.database;
using ghidra.program.model.address;
using ghidra.program.model.listing;
using ghidra.test;
using ghidra.test;
using ghidra.util;

public class MnemonicSearchPluginTest : AbstractGhidraHeadedIntegrationTest {
	private TestEnv env;
	private PluginTool tool;
	private ProgramDB program;
	private MnemonicSearchPlugin plugin;
	private DockingActionIf includeOperandsExcludeConstAction;
	private DockingActionIf excludeOperandsAction;
	private DockingActionIf includeOperandsAction;
	private CodeBrowserPlugin cb;
	private MemorySearchProvider searchProvider;

	/* @Before */
	public void setUp()
    {
		env = new TestEnv();
		tool = env.getTool();
		tool.addPlugin(typeof(ProgramTreePlugin).getName());
		tool.addPlugin(typeof(CodeBrowserPlugin).getName());
		tool.addPlugin(typeof(MarkerManagerPlugin).getName());
		tool.addPlugin(typeof(MemorySearchPlugin).getName());
		tool.addPlugin(typeof(MnemonicSearchPlugin).getName());
		plugin = env.getPlugin(typeof(MnemonicSearchPlugin));
		cb = env.getPlugin(typeof(CodeBrowserPlugin));
		program = (ProgramDB) buildProgram();
		env.showTool(program);

		excludeOperandsAction = getAction(plugin, "Exclude Operands");
		includeOperandsAction = getAction(plugin, "Include Operands");
		includeOperandsExcludeConstAction =
			getAction(plugin, "Include Operands (except constants)");
	}

	private Program buildProgram()
    {
		ProgramBuilder builder = new ProgramBuilder("TestX86", ProgramBuilder._X86);
		builder.createMemory(".text", Long.toHexString(0x1001000), 0x6600);

		//create and disassemble some code
		builder.setBytes("0x01004062", "55 8b ec 81 ec 04 01 00 00");
		builder.disassemble("0x01004062", 9, true);

		return builder.getProgram();
	}

	/* @After */
	public void tearDown()
    {
		env.dispose();
	}

	/* @Test */
	public void testSearchMnemonicOperandsNoConst() {
		makeSelection(tool, program, addr(0x01004062), addr(0x0100406a));
		performAction(includeOperandsExcludeConstAction, cb.getProvider(), true);
		searchProvider = waitForComponentProvider(typeof(MemorySearchProvider));
		assertEquals(
			"01010101 10001011 11101100 10000001 11101100 ........ ........ ........ ........",
			getInput());
	}

	/* @Test */
	public void testSearchMnemonicNoOperandsNoConst() {
		makeSelection(tool, program, addr(0x01004062), addr(0x0100406a));
		performAction(excludeOperandsAction, cb.getProvider(), true);
		searchProvider = waitForComponentProvider(typeof(MemorySearchProvider));
		assertEquals(
			"01010... 10001011 11...... 10000001 11101... ........ ........ ........ ........",
			getInput());

	}

	/* @Test */
	public void testSearchMnemonicOperandsConst() {

		makeSelection(tool, program, addr(0x01004062), addr(0x0100406a));
		performAction(includeOperandsAction, cb.getProvider(), true);
		searchProvider = waitForComponentProvider(typeof(MemorySearchProvider));
		assertEquals(
			"01010101 10001011 11101100 10000001 11101100 00000100 00000001 00000000 00000000",
			getInput());
	}

	/**
	 * Tests that when multiple regions are selected, the user is notified via
	 * pop-up that this is not acceptable.
	 */
	/* @Test */
	public void testMultipleSelection() {

		// First set up two selection ranges.
		AddressRange range1 = new AddressRangeImpl(addr(0x01004062), addr(0x01004064));
		AddressRange range2 = new AddressRangeImpl(addr(0x0100406c), addr(0x0100406e));
		AddressSet addrSet = new AddressSet();
		addrSet.add(range1);
		addrSet.add(range2);

		// Create an event that we can fire to all subscribers, and send it.
		makeSelection(tool, program, addrSet);

		// Now invoke the menu option we want to test.
		performAction(includeOperandsAction, cb.getProvider(), false);

		// Here's the main assert: If the code recognizes that we have multiple selection, the
		// MemSearchDialog will NOT be displayed (an error message pops up instead).  So verify that
		// the dialog is null and we're ok.
		Window errorDialog = waitForWindow("Mnemonic Search Error");
		assertNotNull(errorDialog);
		errorDialog.setVisible(false);
	}

	private Address addr(int offset) {
		return program.getMinAddress().getNewAddress(offset);
	}

	private string getInput() {
		return Swing.runNow(() => searchProvider.getSearchInput());
	}
}
